from __future__ import annotations

from typing import Generic, Literal, TypeVar

from pydantic import BaseModel, Field

T = TypeVar("T")

# "demo"     -> synthetic data generated by SentinelAI; must always be labelled DEMO.
# "replayed" -> a real IDS dataset replayed offline in chronological windows.
DataOrigin = Literal["demo", "replayed"]


class Page(BaseModel, Generic[T]):
    items: list[T]
    total: int
    page: int = Field(ge=1)
    page_size: int = Field(ge=1)
    data_origin: DataOrigin | None = None


class Message(BaseModel):
    ok: bool = True
    message: str
